<template><div class="page"><div class="page-header"><div><el-button link @click="router.back()"><ArrowLeft/>返回</el-button><h1 class="page-title">新建课程</h1><p class="page-description">创建后即可上传该课程的教学资料。</p></div></div><div class="card card-body" style="max-width:760px"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="课程名称" prop="name"><el-input v-model="form.name" placeholder="例如：Python程序设计"/></el-form-item><el-form-item label="课程编号"><el-input v-model="form.code"/></el-form-item><el-form-item label="适用年级"><el-input v-model="form.grade"/></el-form-item><el-form-item label="适用专业"><el-input v-model="form.major"/></el-form-item><el-form-item label="课程简介" class="full"><el-input v-model="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="备注" class="full"><el-input v-model="form.remark" type="textarea" :rows="3"/></el-form-item></div><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="saving" @click="save">创建课程</el-button></el-form></div></div></template><script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{coursesApi}from'../../api';const router=useRouter(),formRef=ref(),saving=ref(false),form=reactive({name:'',code:'',grade:'',major:'',description:'',remark:'',status:'ACTIVE'}),rules={name:[{required:true,message:'课程名称不能为空',trigger:'blur'}]};const save=async()=>{await formRef.value.validate();saving.value=true;try{const c=await coursesApi.create(form);ElMessage.success('课程创建成功');router.push(`/courses/${c.id}`)}finally{saving.value=false}}</script>
